"use client";

import React, { useEffect, useRef, useState } from "react";
import $ from "jquery";

import { useRouter } from "next/navigation";
import { homepageApiStructure } from "@/Apis/HomePage/apis";
import AOS from "aos";

const ServiceSlider = ({ paragraph }) => {
  const sliderRef = useRef(null);
  const router = useRouter();

  // ADDED: state to hold the fetched services, plus loading/error flags
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const handleLeistungenClick = (slug) => {
    router.push(`/leistungen/${slug}`);
  };

  // ADDED: fetch the leistungens from Strapi on mount, and map the API
  // response shape onto the same shape the component/JSX already expects
  // (id, title, description, tags) so the render logic below barely changes.
  useEffect(() => {
    let mounted = true;

    const fetchServices = async () => {
      try {
        const result = await homepageApiStructure.getLeistungens();

        if (!mounted) return;

        const mapped = (result?.data || []).map((item) => ({
          id: item.documentId,
          slug: item.Slug,
          displayId: String(item.id).padStart(2, "0"),
          title: item.Titel,
          description: item.Text,
          tags: (item.tag || []).map((tag) => ({
            id: tag.documentId,
            title: tag.Titel,
          })),
        }));

        setServices(mapped);
      } catch (err) {
        if (mounted) setError(err);
      } finally {
        if (mounted) setLoading(false);
      }
    };

    fetchServices();

    return () => {
      mounted = false;
    };
  }, []);

  // ADDED: Owl Carousel now only initializes once services have actually
  // loaded (it needs real DOM items to attach to — initializing against an
  // empty list would create a broken/empty carousel).
  useEffect(() => {
    if (loading || error || services.length === 0) return;

    let mounted = true;

    const initializeSlider = async () => {
      // Make jQuery globally available
      window.jQuery = $;
      window.$ = $;

      // Load Owl Carousel after jQuery
      await import("owl.carousel");

      if (!mounted || !sliderRef.current) return;

      const slider = $(sliderRef.current);

      if (typeof $.fn.owlCarousel !== "function") {
        console.error("Owl Carousel was not attached to jQuery");
        return;
      }

      // Destroy any existing instance first (guards against double-init if
      // `services` ever updates again after the carousel already ran).
      if (slider.hasClass("owl-loaded")) {
        slider.trigger("destroy.owl.carousel");
      }


            // Refresh AOS once Owl Carousel has actually finished setting
      // itself up (loop mode clones extra slide nodes into the DOM,
      // which changes this row's layout after the fact). Binding to
      // the carousel's own "initialized" event is more reliable here
      // than a generic page-wide observer, since it fires exactly when
      // this specific component's DOM has settled - no guessing.
      slider.on("initialized.owl.carousel", () => {
        requestAnimationFrame(() => {
          AOS.refreshHard();
        });
      });

      // Initialize Owl Carousel
      slider.owlCarousel({
        loop: true,
        margin: 30,
        autoplay: true,
        autoplayHoverPause: true,
        autoplayTimeout: 5000,
        smartSpeed: 400,
        dots: false,
        nav: true,
        autoHeight: true,
        navText: [
          '<img src="/images/prev-arrow.svg" alt="Previous" />',
          '<img src="/images/next-arrow.svg" alt="Next" />',
        ],

        responsive: {
          0: {
            items: 1,
          },
          460: {
            items: 1,
          },
          768: {
            items: 1,
          },
          900: {
            items: 1.6,
          },
          1200: {
            items: 1.7,
          },
        },
      });
    };

    initializeSlider();

    return () => {
      mounted = false;

      if (sliderRef.current) {
        const slider = $(sliderRef.current);

        if (slider.hasClass("owl-loaded")) {
          slider.trigger("destroy.owl.carousel");
        }
      }
    };
    // ADDED: re-run carousel init if the fetched services list changes
  }, [loading, error, services]);

  // Previous slide
  const prevSlide = () => {
    if (sliderRef.current) {
      $(sliderRef.current).trigger("prev.owl.carousel");
    }
  };

  // Next slide
  const nextSlide = () => {
    if (sliderRef.current) {
      $(sliderRef.current).trigger("next.owl.carousel");
    }
  };

  return (
    <div className="row service-slider-row" data-aos="fade-up" data-aos-delay="200">
      {/* Left Content */}
      <div className="col-12 col-lg-4 content-col align-self-end mt-4">
        <p>{paragraph}</p>
        <div className="slider-buttons d-none d-lg-block">
          <button type="button" className="btn-previous" onClick={prevSlide}>
            <img src="/images/prev-arrow.svg" alt="Previous" />
          </button>
          <button type="button" className="btn-next" onClick={nextSlide}>
            <img src="/images/next-arrow.svg" alt="Next" />
          </button>
        </div>
      </div>
      {/* Slider */}
      <div className="col-12 col-lg-7 ms-auto slider-col mt-4">
        <div className="service-slider">
          {/* ADDED: basic loading / error / empty states around the fetched data */}
          {loading && <p>Wird geladen...</p>}
          {error && <p>Leistungen konnten nicht geladen werden.</p>}
          {!loading && !error && services.length === 0 && (
            <p>Keine Leistungen gefunden.</p>
          )}

          {!loading && !error && services.length > 0 && (
            <div ref={sliderRef} className="owl-carousel owl-theme">
              {services.map((service, index) => (
                <div className="item" key={service.id}>
                  <div onClick={() => handleLeistungenClick(service.slug)}>
                    <div className="item-count">{index + 1}</div>
                    <h3>{service.title}</h3>
                    <p>{service.description}</p>
                    <hr />
                    <div className="item-tags">
                    {service.tags.map((tag) => (
                        <span key={tag.id}>
                          {tag.title}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ServiceSlider;